from pathlib import Path
import re
from docx import Document
from docx.shared import Cm, Pt, RGBColor
from docx.enum.text import WD_ALIGN_PARAGRAPH
from docx.enum.section import WD_SECTION_START
from docx.oxml import OxmlElement
from docx.oxml.ns import qn
from PIL import Image, ImageDraw, ImageFont

root=Path(__file__).parent
def p(d,t='',style=None):
    q=d.add_paragraph(t,style); return q
def h(d,t): return p(d,t,'Heading 1')
def make(title,code,standard,sections,annotation):
    d=Document(); s=d.sections[0]
    s.page_width=Cm(21); s.page_height=Cm(29.7)
    s.left_margin=Cm(3); s.right_margin=Cm(1.5); s.top_margin=Cm(2); s.bottom_margin=Cm(2)
    for name in ['Normal','Title','Heading 1','Heading 2']:
        st=d.styles[name]; st.font.name='Times New Roman'; st.font.size=Pt(12); st.font.color.rgb=RGBColor(0,0,0)
        for key in list(st.element.get_or_add_rPr().rFonts.attrib):
            if 'Theme' in key: del st.element.rPr.rFonts.attrib[key]
        st.paragraph_format.line_spacing=1.15; st.paragraph_format.space_after=Pt(5)
        for b in list(st.element.xpath('.//w:pBdr')): b.getparent().remove(b)
    d.styles['Normal'].paragraph_format.first_line_indent=Cm(1.25)
    d.styles['Normal'].paragraph_format.alignment=WD_ALIGN_PARAGRAPH.JUSTIFY
    for n in ['Heading 1','Heading 2']:
        d.styles[n].font.bold=True; d.styles[n].paragraph_format.first_line_indent=Cm(0)
        d.styles[n].paragraph_format.space_before=Pt(10)
    def c(t,before=10,size=14):
        q=p(d,t); q.alignment=WD_ALIGN_PARAGRAPH.CENTER; q.paragraph_format.first_line_indent=Cm(0); q.paragraph_format.space_before=Pt(before)
        q.runs[0].font.size=Pt(size)
    c('Организация ______________________________',0,12)
    q=p(d,'УТВЕРЖДАЮ\nРуководитель учебного проекта\n____________ / __________________\n«____» ______________ 2026 г.')
    q.alignment=WD_ALIGN_PARAGRAPH.RIGHT; q.paragraph_format.first_line_indent=Cm(0)
    c('ВЕБ-ПРИЛОЖЕНИЕ BARMIXHUB',70,16); c(title); c('ЛИСТ УТВЕРЖДЕНИЯ'); c(code+'-ЛУ\nЭлектронный документ',10,12)
    q=p(d,'Разработчик ____________ / __________________\nГруппа __________________\nДата __________________\n\nНормоконтролер ____________ / __________________\nДата __________________')
    q.alignment=WD_ALIGN_PARAGRAPH.RIGHT; q.paragraph_format.first_line_indent=Cm(0); q.paragraph_format.space_before=Pt(60)
    c('2026',40)
    s=d.add_section(WD_SECTION_START.NEW_PAGE); s.different_first_page_header_footer=True
    pg=OxmlElement('w:pgNumType'); pg.set(qn('w:start'),'1'); s._sectPr.append(pg)
    s.header.is_linked_to_previous=False
    q=s.header.paragraphs[0]; q.alignment=WD_ALIGN_PARAGRAPH.CENTER; q.paragraph_format.first_line_indent=Cm(0)
    fld=OxmlElement('w:fldSimple'); fld.set(qn('w:instr'),'PAGE'); q._p.append(fld)
    q=p(d,'УТВЕРЖДЕН\n'+code+'-ЛУ'); q.paragraph_format.first_line_indent=Cm(0); q.alignment=WD_ALIGN_PARAGRAPH.LEFT
    c('ВЕБ-ПРИЛОЖЕНИЕ BARMIXHUB',140,16)
    q=p(d,title,'Title'); q.alignment=WD_ALIGN_PARAGRAPH.CENTER
    c(code+'\nЭлектронный документ',20,12)
    q=p(d,'Листов '); q.alignment=WD_ALIGN_PARAGRAPH.CENTER; q.paragraph_format.first_line_indent=Cm(0)
    q.add_run('4')
    c('2026',160)
    d.add_page_break(); h(d,'Аннотация'); p(d,annotation)
    p(d,'Основание: практическая работа № 1 по дисциплине «Тестирование и верификация программного обеспечения». '+standard)
    h(d,'Содержание')
    q=p(d); fld=OxmlElement('w:fldSimple'); fld.set(qn('w:instr'),'TOC \\o "1-2" \\h \\z \\u'); q._p.append(fld)
    d.add_page_break()
    for heading,paras in sections:
        h(d,heading)
        for text in paras:
            if text=='DIAGRAM':
                d.add_picture(str(root/'architecture.png'),width=Cm(16)); p(d,'Рисунок 1 — Взаимодействие компонентов локальной версии')
            else: p(d,re.sub(r'\s+', ' ', text).strip())
    d.core_properties.author=''; d.core_properties.title=title
    file=root/(title.replace(' ','_')+'_BarMixHub.docx'); d.save(file)
    print(file.name)

def mdparas(file):
    text=(root/file).read_text(encoding='utf-8')
    return [re.sub(r'`','',x.strip()) for x in text.split('\n\n') if x.strip() and not x.startswith('#') and not x.startswith('```')]

# Схема является программной иллюстрацией, а не сгенерированным изображением.
im=Image.new('RGB',(1400,690),'white'); draw=ImageDraw.Draw(im); font=ImageFont.truetype('C:/Windows/Fonts/times.ttf',30)
def box(x,y,w,txt):
    draw.rectangle((x,y,x+w,y+90),outline='black',width=3); draw.multiline_text((x+18,y+14),txt,font=font,fill='black',spacing=3)
def arrow(a,b):
    draw.line((a,b),fill='black',width=3); x,y=b; draw.polygon([(x,y),(x-9,y-17),(x+9,y-17)],fill='black')
box(350,10,700,'Браузер — React и React Router')
